{\frac{1}{\Delta t}+\frac{\partial v_y}{\partial y}}
\end{aligned}
\]

\[
\begin{aligned}
\gamma_z
&=\lim_{\Delta t\to0}\frac{\Delta\alpha+\Delta\beta}{\Delta t}\\
&=\lim_{\Delta t\to0}\frac{1}{\Delta t}
\left(
\frac{\frac{\partial v_y}{\partial x}}
{\frac{1}{\Delta t}+\frac{\partial v_x}{\partial x}}
+
\frac{\frac{\partial v_x}{\partial y}}
{\frac{1}{\Delta t}+\frac{\partial v_y}{\partial y}}
\right)\\
&=\lim_{\Delta t\to0}
\left(
\frac{\frac{\partial v_y}{\partial x}}
{1+\frac{\partial v_x}{\partial x}\Delta t}
+
\frac{\frac{\partial v_x}{\partial y}}
{1+\frac{\partial v_y}{\partial y}\Delta t}
\right)\\
&=\frac{\partial v_y}{\partial x}+\frac{\partial v_x}{\partial y}
\end{aligned}
\]

